sdl:
directive @cost(weight: String!) on ARGUMENT_DEFINITION | ENUM | FIELD_DEFINITION | INPUT_FIELD_DEFINITION | OBJECT | SCALAR
directive @listSize(
  assumedSize: Int
  slicingArguments: [String!]
  sizedFields: [String!]
  requireOneSlicingArgument: Boolean = true
) on FIELD_DEFINITION
type User { name: String }
type Query { users(first: Int = 3): [User] @listSize(slicingArguments: "first") }

operation:
query Example($first: Int = 4) {
  schemaDefault: users { name }
  operationDefault: users(first: $first) { name }
}
